def clean(df):
    df = df.drop_duplicates(subset=["Order_ID"], keep='first')
    df["Region"] = df["Region"].str.strip().str.title()
    allowed_regions = ["North", "South", "East", "West"]
    df = df[df["Region"].isin(allowed_regions)]
    df = df[df["Quantity"] >= 1]
    return df

def answer(df):
    electronics = df[df["Category"] == "Electronics"]
    grouped = electronics.groupby("Region")["Revenue"].sum().reset_index()
    if len(grouped) == 1:
        return {"all": grouped["Revenue"].iloc[0]}
    else:
        return {row["Region"]: row["Revenue"] for row in grouped}
